DROP TABLE IF EXISTS `films`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `films` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(120) NOT NULL,
  `title` varchar(160) NOT NULL,
  `title_en` varchar(160) DEFAULT NULL,
  `logline` text DEFAULT NULL,
  `synopsis_md` mediumtext DEFAULT NULL,
  `genre` varchar(120) DEFAULT NULL,
  `duration_min` smallint(5) unsigned DEFAULT NULL,
  `duration_note` varchar(160) DEFAULT NULL,
  `year` smallint(5) unsigned DEFAULT NULL,
  `poster_media_id` int(10) unsigned DEFAULT NULL,
  `trailer_url` varchar(255) DEFAULT NULL,
  `credits_md` text DEFAULT NULL,
  `actors` varchar(255) DEFAULT NULL,
  `awards_md` text DEFAULT NULL,
  `badge` varchar(120) DEFAULT NULL,
  `related_tag` varchar(120) DEFAULT NULL,
  `status` enum('released','in_production','in_development') NOT NULL DEFAULT 'released',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` smallint(6) NOT NULL DEFAULT 0,
  `seo_title` varchar(120) DEFAULT NULL,
  `seo_desc` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_films_slug` (`slug`),
  KEY `fk_films_poster` (`poster_media_id`),
  CONSTRAINT `fk_films_poster` FOREIGN KEY (`poster_media_id`) REFERENCES `media` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

