INSERT INTO `films` VALUES (1,'doi','ĐỢI','WAITING','An giam mình trong chiếc lồng tâm lý mang tên chờ đợi người khác, và trong chính lựa chọn của mình. Phải qua hết những điều ấy, cô mới tìm được lối ra.','Giữa dòng người hối hả và nhịp sống cuồn cuộn của Sài Gòn, An – một cô gái trẻ di chuyển bằng xe lăn điện – phải tự mình thực hiện một hành trình quan trọng. \n\nNhững bậc tam cấp cao vút, những gờ vỉa hè thiếu đường dốc và ánh nhìn ái ngại của người xung quanh tưởng chừng là rào cản lớn nhất. Nhưng rào cản nghiệt ngã nhất lại chính là chiếc lồng tâm lý mang tên \"chờ đợi\": Chờ đợi một bàn tay xa lạ đẩy giúp, chờ đợi sự cảm thông từ xã hội, và chờ đợi một phép màu giải thoát.\n\nChỉ khi quyết định dừng việc chờ đợi và tự mình đối diện với nỗi sợ hãi thầm kín, An mới thực sự tìm thấy chiếc chìa khóa giải thoát tâm hồn mình.','Phim ngắn · Chính kịch',8,'6 phút (bản dự thi)',2026,11,NULL,'- Biên kịch: Thanh Thanh\n- Vai chính (An): Thanh Thanh\n- Pitching trước: ĐD Trịnh Đình Lê Minh, chị Phạm Thị Hảo','Thanh Thanh','- Top 7 Grand Finalists Inspiring Asia Micro Film Festival 2026 (Manila, Philippines)\n- Bán kết Inspiring Asia 2026 (1 trong 4 đại diện Việt Nam)\n- Top 6 Phim ngắn xuất sắc Chung kết Inspiring Vietnam 2026 (SIHUB, TP.HCM)','Top 7 Grand Finalists · Inspiring Asia 2026','phimngandoi','released',1,1,'Phim ngắn ĐỢI (WAITING) | Biên kịch Thanh Thanh','Phim ngắn ĐỢI (WAITING) của Biên kịch Thanh Thanh lọt Top 7 Grand Finalists Inspiring Asia 2026 tại Manila. Tác phẩm điện ảnh độc lập giàu cảm xúc.','2026-10-13 20:02:51','2026-10-14 09:03:06');
INSERT INTO `films` VALUES (2,'dua-con-den-tu-coi-am','Đứa con đến từ cõi âm','The Child From The Netherworld','Một bí mật gia đình bị chôn vùi sống dậy qua hiện tượng tâm linh kỳ bí, buộc người mẹ phải đối diện với góc tối nhất trong tâm hồn để tìm sự cứu rỗi.','\"Đứa con đến từ cõi âm\" là dự án phim truyện điện ảnh dài đầu tay của biên kịch Thanh Thanh, khai thác đề tài kinh dị tâm lý (Psychological Horror) kết hợp yếu tố tâm linh bản địa Việt Nam.\n\nCâu chuyện xoay quanh một gia đình tưởng chừng êm ấm nhưng che giấu một bí mật đen tối từ quá khứ. Khi những hiện tượng siêu nhiên dị thường liên tiếp xảy ra trong ngôi nhà cổ, ranh giới giữa thực và ảo, giữa tình mẫu tử thiêng liêng và sự ám ảnh tội lỗi dần bị xóa nhòa, đẩy các nhân vật vào cuộc chiến sinh tồn khốc liệt để tìm lại sự cứu rỗi.','Phim điện ảnh · Kinh dị tâm lý',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'- Top 7 From Script To Screen (Mùa 1) – Chương trình ươm mầm tài năng biên kịch điện ảnh\n- Kịch bản được cố vấn bởi các chuyên gia điện ảnh uy tín','Top 7 From Script To Screen (Mùa 1)',NULL,'in_development',0,2,'Phim \"Đứa con đến từ cõi âm\" | Biên kịch Thanh Thanh','Dự án phim điện ảnh kinh dị tâm lý Đứa con đến từ cõi âm của Biên kịch Thanh Thanh - Tác phẩm lọt Top 7 From Script To Screen (Mùa 1).','2026-10-13 20:02:51','2026-10-14 09:03:06');
