INSERT INTO `settings` VALUES (4,'mission_intro','Mình là Thanh Thanh, biên kịch và vai chính của phim ngắn ĐỢI. Ở đây mình kể chuyện hậu trường, những “lần đầu tiên”, và những giới hạn mà không ai có quyền đặt ra cho mình.','2026-10-13 20:02:51','2026-10-13 20:02:51');
